import{_ as i,a0 as u,w as s,s as a,ao as p,I as n,x as r,a1 as l,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"我的 Linux 故事：從用户到貢獻者 | LCTT x X-CMD","titleTemplate":false,"description":"我的 Linux 故事：從用户到貢獻者 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我的 Linux 故事：從用户到貢獻者 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我的 Linux 故事：從用户到貢獻者 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200713 My Linux story- From Linux user to contributor","title":"我的 Linux 故事：從用户到貢獻者","tag":"202007","desc":""},"relativePath":"202007/20200713 My Linux story- From Linux user to contributor.md","filePath":"[post].md"}'),d={name:"202007/20200713 My Linux story- From Linux user to contributor.md"};function m(x,t,f,L,b,T){const o=u("Link");return s(),a("div",null,[t[24]||(t[24]=p('<h1 id="我的-linux-故事-從用户到貢獻者" tabindex="-1">我的 Linux 故事：從用户到貢獻者 <a class="header-anchor" href="#我的-linux-故事-從用户到貢獻者" aria-label="Permalink to “我的 Linux 故事：從用户到貢獻者”">​</a></h1><blockquote><p>開源社區歡迎來自不同背景和技能的貢獻者。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202007/22/114140tfuubuvcfgujrcab.jpg" alt=""></p><p>我是一名 IT 專業人士，擁有超過 15 年經驗，擔任過不同職位 —— 包括系統管理員、高級 Linux 管理員、DevOps 工程師、自動化顧問和高級<ruby>敏捷專家<rt>scrum master</rt></ruby>。我開始是在 Ubuntu 上學習 Linux，但是後來作為系統管理員轉到 CentOS，然後我又轉到 Fedora 作為個人使用。但是我對技術的喜愛要遠比我使用第一個 Linux 發行版要早的多，而且是來自於一部電影。</p><p>我最喜歡的電影是《<ruby>黑客<rt>Hackers</rt></ruby>》。最精彩的一幕發生在電影的開頭。電影一開始，一羣特工衝進一所房子抓捕臭名昭著的黑客 Zero Cool。我們馬上發現 Zero Cool 其實是 11 歲的 Dade Murphy，他在一天之內成功癱瘓了 1507 台計算機系統。他被指控犯罪，他的家人被處以重罰。而且，在他 18 歲之前，他都被禁止使用電腦或按鍵式電話。</p><p><ruby>勞倫斯·梅森<rt>Laurence Mason</rt></ruby>扮演的 Paul Cook，又名 Nikon 勳爵，是我最喜歡角色。其中一個主要原因是，我從沒有看過一個黑客電影裏面的人物長的像我，所以我被他的形象深深吸引了。他很神秘。這讓我耳目一新，並且感到自豪，我對 IT 充滿了熱情，我也是一個和他很像的極客。</p><p><img src="https://opensource.com/sites/default/files/uploads/taz_with_astronaut_0.png" alt="Taz with astronaut" title="Taz with astronaut"></p><h3 id="成為一個-linux-貢獻者" tabindex="-1">成為一個 Linux 貢獻者 <a class="header-anchor" href="#成為一個-linux-貢獻者" aria-label="Permalink to “成為一個 Linux 貢獻者”">​</a></h3><p>15 年前，我開始使用 Linux。當我成為一個 Linux 管理員的時候，Linux 就成了我的激情所在。我一直嘗試找到某種方式能夠為開源作出貢獻，當時我還不知道該從哪開始。因為這個社區實在是太大了，我不知道自己能否真正成為一個有影響力的人，但當我發現一些人認可我的興趣，還對我進行指導，我開始徹底打開心扉，問各種問題，並且從社區中學習。自從那以後，Fedora 社區一直是我做貢獻的最主要社區。</p><p>我現在對於向開源做貢獻還是有點稚嫩。當我意識到我可以用代碼以外的方式來貢獻時，我對開源的想法發生了改變。我更喜歡通過文檔做一些貢獻，因為我本質上不是一個軟件開發人員，而且社區裏面最迫切的需求正是文檔。請記住：用户的技能和開發人員的技能同樣重要。</p><h3 id="我的硬件是什麼" tabindex="-1">我的硬件是什麼？ <a class="header-anchor" href="#我的硬件是什麼" aria-label="Permalink to “我的硬件是什麼？”">​</a></h3><p>硬件也很重要，而且現在幾乎所有東西都可以運行 Linux。現在，我家裏的配置包括：</p><ul><li>聯想 Thinksever TS140，64 GB 內存，4 x 1 TB SSD 和一個存儲數據的 1 TB 機械硬盤</li><li>使用 RAID 5 配置的 164 TB Synology NAS</li><li>輸入輸出使用羅技 MX Master 和 MX Master 2S</li><li>一個定製的並且符合人體工學的 Kinesis Advantage 2 鍵盤</li><li>兩個 38 寸 LG 超寬曲面顯示器和一個 34 寸 LG 超寬顯示器</li><li>一台配備 i7 六核十二線程 CPU 和 16.1 英寸 IPS 顯示器的 System76 筆記本</li></ul><p>我很喜歡 Fedora 處理外置設備的方式，比如説我的鼠標和鍵盤。一切都完美融合。即插即用工作正常，性能從來不受影響。</p><p><img src="https://opensource.com/sites/default/files/uploads/fedora_double_monitor_setup.jpg" alt="Fedora double monitor setup" title="Fedora double monitor setup"></p><h3 id="軟件是什麼" tabindex="-1">軟件是什麼？ <a class="header-anchor" href="#軟件是什麼" aria-label="Permalink to “軟件是什麼？”">​</a></h3><p>使用開源軟件對我的工作非常重要。我依賴於：</p>',17)),n("ul",null,[t[2]||(t[2]=n("li",null,"Fedora 30 作為我日常使用的 Linux 發行版",-1)),t[3]||(t[3]=n("li",null,[r("Wekan 作為我的項目的開源"),n("ruby",null,[r("看板"),n("rt",null,"kanban")])],-1)),n("li",null,[l(o,{href:"https://fedoramagazine.org/install-atom-fedora/"},{default:e(()=>[...t[0]||(t[0]=[r("Atom",-1)])]),_:1}),t[1]||(t[1]=r(" 作為我的文本編輯器",-1))]),t[4]||(t[4]=n("li",null,"Terminator 作為我日常使用的終端，因為它的網格佈局以及豐富的鍵盤快捷鍵",-1)),t[5]||(t[5]=n("li",null,"Neofetch 用來顯示每次登錄到終端時的系統信息",-1))]),t[25]||(t[25]=n("p",null,"最後同樣重要的是，我把 Powerline、Powerlevel9k 和 Vim-Powerline 搞到我的終端上來跟別人裝酷。",-1)),t[26]||(t[26]=n("p",null,[n("img",{src:"https://opensource.com/sites/default/files/uploads/fedora_screens.jpg",alt:"Multiple fedora screens",title:"Multiple fedora screens"})],-1)),t[27]||(t[27]=n("h3",{id:"linux-讓我們走到一起",tabindex:"-1"},[r("Linux 讓我們走到一起 "),n("a",{class:"header-anchor",href:"#linux-讓我們走到一起","aria-label":"Permalink to “Linux 讓我們走到一起”"},"​")],-1)),t[28]||(t[28]=n("p",null,"美國是個大熔爐，我也是這麼看待 Linux 和像 Fedora 項目這樣的特定社區的。在每個 Linux 社區中，對於不同的貢獻都有很大的空間。也有很多方式可以參與進來，而且對於新的想法，也總是有發揮的空間。通過分享我過去 15 年在開源方面的經驗，我希望幫助更多在科技領域的少數族裔體會到來自開源社區對多樣性和包容性的認同感。",-1)),n("p",null,[n("em",null,[t[7]||(t[7]=r("編者注：這篇文章改編自",-1)),l(o,{href:"https://fedoramagazine.org/taz-brown-how-do-you-fedora/"},{default:e(()=>[...t[6]||(t[6]=[r("“Taz Brown：你怎麼搞 Fedora？”",-1)])]),_:1}),t[8]||(t[8]=r("，並得到許可重新發布",-1))])]),t[29]||(t[29]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=r("via: ",-1)),l(o,{href:"https://opensource.com/article/20/7/linux-user-contributor"},{default:e(()=>[...t[9]||(t[9]=[r("https://opensource.com/article/20/7/linux-user-contributor",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=r("作者：",-1)),l(o,{href:"https://opensource.com/users/heronthecli"},{default:e(()=>[...t[11]||(t[11]=[r("Taz Brown",-1)])]),_:1}),t[16]||(t[16]=r(" 選題：",-1)),l(o,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[12]||(t[12]=[r("lujun9972",-1)])]),_:1}),t[17]||(t[17]=r(" 譯者：",-1)),l(o,{href:"https://github.com/Yufei-Yan"},{default:e(()=>[...t[13]||(t[13]=[r("Yufei-Yan",-1)])]),_:1}),t[18]||(t[18]=r(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[14]||(t[14]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=r("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[19]||(t[19]=[r("LCTT",-1)])]),_:1}),t[22]||(t[22]=r(" 原創編譯，",-1)),l(o,{href:"https://linux.cn/"},{default:e(()=>[...t[20]||(t[20]=[r("Linux中國",-1)])]),_:1}),t[23]||(t[23]=r(" 榮譽推出",-1))])])}const k=i(d,[["render",m]]);export{C as __pageData,k as default};
